import sys
sys.path.insert(0, ".")
import numpy as np, gate

def make(dtype, eps):
    def layernorm(x):
        wide = np.asarray(x, dtype=np.float64)
        c = wide - np.mean(wide, axis=-1, keepdims=True)
        var = np.mean(c * c, axis=-1, keepdims=True)
        if eps == 0.0:
            return np.where(var > 0, c / np.sqrt(np.where(var > 0, var, 1.0)), 0.0).astype(dtype)
        return (c / np.sqrt(var + eps)).astype(dtype)
    return layernorm

for eps in (1e-5, 1e-12, 0.0):
    k = make(np.float64, eps)
    for laws in (False, True):
        v = gate.check(k, laws)
        print(f"float64 output eps={eps:g} laws={'on ' if laws else 'off'}  declarative={v['declarative'][0]}/9  reference={v['reference'][0]}/9")
        print("     decl first:", v['declarative'][2][:120])
        print("     per law:", {p: c for p, c in gate.per_property(k, laws).items()})
